_CORE_SRC = '# Action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: cost_p = 3.0 * (trucks of p not on p\'s base)\n#              + 1.5 * (scooters of p not on p\'s base).\n# Moves precede service; stock then regenerates, rounded to two decimals.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 60\nCAPACITY = {"truck": 8, "scooter": 3}\nCOST = {"truck": 3.0, "scooter": 1.5}\nSPEED = {"truck": 1, "scooter": 2}\n\n\ndef payout(own, other, stock):\n    denominator = max(own + other, stock)\n    if denominator <= 0:\n        return 0.0\n    return own * stock / denominator\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.dist = None\n        self.reachable = None\n        self.previous_opponent = {}\n        self.previous_routes = {}\n        self.previous_turn = None\n        self.movement_rate = 0.65\n        self.bad_reports = 0\n\n    def _prepare_map(self, obs):\n        n = int(obs["n_nodes"])\n        adj = [[] for _ in range(n)]\n        for a, b in obs["edges"]:\n            adj[a].append(b)\n            adj[b].append(a)\n        for row in adj:\n            row.sort()\n        dist = []\n        for source in range(n):\n            row = [-1] * n\n            row[source] = 0\n            queue = deque([source])\n            while queue:\n                u = queue.popleft()\n                for v in adj[u]:\n                    if row[v] < 0:\n                        row[v] = row[u] + 1\n                        queue.append(v)\n            dist.append(row)\n        self.dist = dist\n        self.reachable = {\n            speed: [\n                [v for v in range(n) if 0 <= dist[u][v] <= speed]\n                for u in range(n)\n            ]\n            for speed in (1, 2)\n        }\n\n    def _step(self, source, target, speed):\n        if self.dist[source][target] <= speed:\n            return target\n        return min(\n            self.reachable[speed][source],\n            key=lambda v: (self.dist[v][target], v),\n        )\n\n    def _route(self, source, target, speed, horizon, dwell, home):\n        route = []\n        arrived = 0\n        returning = False\n        for _ in range(horizon):\n            if returning:\n                source = self._step(source, home, speed)\n            else:\n                source = self._step(source, target, speed)\n                if source == target:\n                    arrived += 1\n                    if arrived >= dwell:\n                        returning = True\n            route.append(source)\n        return route\n\n    def _predict_opponent(self, obs, horizon, deadline):\n        n = int(obs["n_nodes"])\n        units = obs.get("opponent_units", {})\n        home = int(obs["opponent_base"])\n        positions = {uid: int(data[1]) for uid, data in units.items()}\n        if self.previous_turn == int(obs["turn"]) - 1 and self.previous_opponent:\n            observed = sum(\n                positions[uid] != self.previous_opponent.get(uid, positions[uid])\n                for uid in sorted(positions)\n            ) / max(1, len(positions))\n            self.movement_rate = 0.55 * self.movement_rate + 0.45 * observed\n        self.previous_opponent = positions.copy()\n\n        # The stationary hypothesis gets more weight against stationary players.\n        moving_weight = min(0.90, max(0.10, 0.20 + self.movement_rate))\n        frozen = [0.0] * n\n        for uid, (kind, node) in units.items():\n            frozen[node] += CAPACITY[kind]\n        stock = list(obs["stock"])\n        result = []\n        for h in range(horizon):\n            allocated = [0.0] * n\n            for uid in sorted(units, key=lambda u: (-CAPACITY[units[u][0]], u)):\n                kind = units[uid][0]\n                cap, cost, speed = CAPACITY[kind], COST[kind], SPEED[kind]\n                source = positions[uid]\n                best, best_value = source, -1e100\n                for v in self.reachable[speed][source]:\n                    gain = min(stock[v], allocated[v] + cap) - min(\n                        stock[v], allocated[v]\n                    )\n                    gain -= cost if v != home else 0.0\n                    # A small return preference avoids predicting endless loss-making trips.\n                    gain -= 0.12 * cost * self.dist[v][home] / speed\n                    if v == source:\n                        gain += 0.025\n                    if gain > best_value:\n                        best, best_value = v, gain\n                positions[uid] = best\n                allocated[best] += cap\n            expected = [\n                moving_weight * allocated[v] + (1.0 - moving_weight) * frozen[v]\n                for v in range(n)\n            ]\n            result.append(expected)\n            stock = [\n                round(min(obs["stock_max"][v],\n                          max(0.0, stock[v] - expected[v]) + obs["regen"][v]), 2)\n                for v in range(n)\n            ]\n        return result\n\n    def _plan(self, obs, horizon, opponent, deadline):\n        n = int(obs["n_nodes"])\n        home = int(obs["player_base"])\n        units = obs.get("player_units", {})\n        stock = obs["stock"]\n        maximum = obs["stock_max"]\n        regen = obs["regen"]\n        turn = int(obs.get("turn", 0))\n        discount = [0.94 ** h for h in range(horizon)]\n        total = [[0.0] * n for _ in range(horizon)]\n        routes = {}\n\n        # A legal, cheap fallback is always available: head home.\n        for uid in sorted(units):\n            kind, source = units[uid]\n            speed = SPEED[kind]\n            route = self._route(source, home, speed, horizon, horizon, home)\n            old = self.previous_routes.get(uid)\n            if self.previous_turn == turn - 1 and old and len(old) > 1:\n                candidate = old[1:] + [old[-1]]\n                if self.dist[source][candidate[0]] <= speed:\n                    route = candidate[:horizon]\n                    while len(route) < horizon:\n                        route.append(route[-1])\n            routes[uid] = route\n            for h, v in enumerate(route):\n                total[h][v] += CAPACITY[kind]\n\n        def node_value(v, extra_route=None, cap=0):\n            s = stock[v]\n            value = 0.0\n            for h in range(horizon):\n                own = total[h][v]\n                if extra_route is not None and extra_route[h] == v:\n                    own += cap\n                other = opponent[h][v]\n                value += discount[h] * (\n                    payout(own, other, s) - payout(other, own, s)\n                )\n                s = round(min(maximum[v], max(0.0, s - own - other) + regen[v]), 2)\n            return value\n\n        def route_cost(route, kind):\n            cost = COST[kind]\n            value = sum(discount[h] * cost for h, v in enumerate(route) if v != home)\n            # Account for costs beyond the planning window, but not beyond game end.\n            if turn + horizon < N_TURNS:\n                v = route[-1]\n                return_time = (self.dist[v][home] + SPEED[kind] - 1) // SPEED[kind]\n                value += discount[-1] * cost * return_time * 0.45\n            return value\n\n        order = sorted(units, key=lambda u: (-CAPACITY[units[u][0]], u))\n        for sweep in range(2):\n            for uid in order:\n                if time.perf_counter() >= deadline:\n                    return routes\n                kind, source = units[uid]\n                cap, speed = CAPACITY[kind], SPEED[kind]\n                old = routes[uid]\n                for h, v in enumerate(old):\n                    total[h][v] -= cap\n                baseline = [node_value(v) for v in range(n)]\n\n                def evaluate(route):\n                    affected = sorted(set(route))\n                    return (\n                        sum(node_value(v, route, cap) - baseline[v] for v in affected)\n                        - route_cost(route, kind)\n                    )\n\n                best = old\n                best_score = evaluate(old) + 0.035  # Target/path hysteresis.\n                candidates_seen = {tuple(old)}\n                for target in range(n):\n                    arrival = max(1, (self.dist[source][target] + speed - 1) // speed)\n                    if arrival > horizon:\n                        continue\n                    dwells = (1, 2, horizon) if target != home else (horizon,)\n                    for dwell in dwells:\n                        if time.perf_counter() >= deadline:\n                            break\n                        route = self._route(\n                            source, target, speed, horizon, dwell, home\n                        )\n                        key = tuple(route)\n                        if key in candidates_seen:\n                            continue\n                        candidates_seen.add(key)\n                        score = evaluate(route)\n                        if score > best_score + 1e-9:\n                            best_score, best = score, route\n                routes[uid] = best\n                for h, v in enumerate(best):\n                    total[h][v] += cap\n        return routes\n\n    def _legal_action(self, obs, routes):\n        moves = {}\n        n = int(obs["n_nodes"])\n        for uid in sorted(routes):\n            if uid not in obs.get("player_units", {}) or not routes[uid]:\n                continue\n            kind, source = obs["player_units"][uid]\n            destination = int(routes[uid][0])\n            if (\n                0 <= destination < n\n                and 0 <= self.dist[source][destination] <= SPEED[kind]\n                and destination != source\n            ):\n                moves[str(uid)] = int(destination)\n        return {"moves": moves}\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        if self.dist is None:\n            self._prepare_map(obs)\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n        turn = int(obs.get("turn", 0))\n        horizon = max(1, min(7, N_TURNS - turn))\n        opponent = self._predict_opponent(obs, horizon, deadline)\n        routes = self._plan(obs, horizon, opponent, deadline)\n        action = self._legal_action(obs, routes)\n        # Even after bad feedback, the same explicit start-state legality check\n        # is sufficient; discard warm starts to avoid propagating a stale plan.\n        self.previous_routes = routes if self.bad_reports < 2 else {}\n        self.previous_turn = turn\n        return action\n'
