_FALLBACK_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: 3.0 per truck and 1.5 per scooter not on its own player\'s base;\n# couriers on their own base cost nothing and serve nothing.\n#\n# Conservative fallback: harvest only inside the free-return radius of home.\n# Every normal deployment earns a clearly positive immediate marginal profit,\n# and can return home next turn without paying another running cost.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 60\nUNIT_TYPES = {\n    "truck": (8, 3.0, 1),\n    "scooter": (3, 1.5, 2),\n}\nMIN_PROFIT = 0.50\n\n\ndef served(own_capacity, opponent_capacity, stock):\n    """The specification\'s proportional-capacity payout, including zero stock."""\n    denominator = max(own_capacity + opponent_capacity, stock)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * stock / denominator\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        if 0 <= u < n and 0 <= v < n and u != v:\n            adjacency[u].append(v)\n            adjacency[v].append(u)\n    adjacency = [sorted(set(neighbors)) for neighbors in adjacency]\n\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if distance[neighbor] == -1:\n                    distance[neighbor] = distance[node] + 1\n                    queue.append(neighbor)\n        distances.append(distance)\n    return distances\n\n\ndef return_liability(distance, speed, cost):\n    """Costs of returning directly home, excluding the free arrival turn."""\n    if distance < 0:\n        return float("inf")\n    steps = (distance + speed - 1) // speed\n    return cost * max(0, steps - 1)\n\n\ndef homeward_step(position, base, speed, distances):\n    """A legal shortest return step; does not depend on earlier calls."""\n    remaining = distances[position][base]\n    if remaining < 0:\n        return position\n    candidates = [\n        node for node in range(len(distances))\n        if 0 <= distances[position][node] <= speed\n        and 0 <= distances[node][base] <= remaining\n    ]\n    return min(candidates, key=lambda node: (distances[node][base], node))\n\n\ndef make_plan(obs, distances):\n    n = len(distances)\n    base = int(obs["player_base"])\n    units = obs.get("player_units", {})\n    stock = obs.get("stock", [])\n    turn = int(obs.get("turn", 0))\n    if turn >= N_TURNS or len(stock) != n:\n        return {}\n\n    opponent_capacity = [0] * n\n    for unit_type, position in obs.get("opponent_units", {}).values():\n        if unit_type in UNIT_TYPES and 0 <= position < n:\n            opponent_capacity[position] += UNIT_TYPES[unit_type][0]\n\n    allocated_capacity = [0] * n\n    plan = {}\n\n    # Trucks exploit large stocks efficiently; scooters take smaller leftovers.\n    # Every allocation uses marginal revenue, not the node\'s whole stock.\n    ordered_units = sorted(\n        units,\n        key=lambda uid: (\n            0 if units[uid][0] == "truck" else 1,\n            uid,\n        ),\n    )\n    for uid in ordered_units:\n        unit_type, position = units[uid]\n        if unit_type not in UNIT_TYPES or not 0 <= position < n:\n            continue\n        capacity, cost, speed = UNIT_TYPES[unit_type]\n        fallback = homeward_step(position, base, speed, distances)\n        destination = fallback\n        old_liability = return_liability(\n            distances[position][base], speed, cost\n        )\n        best_key = None\n\n        for node in range(n):\n            travel = distances[position][node]\n            home_distance = distances[node][base]\n            if node == base or not 0 <= travel <= speed:\n                continue\n\n            # No multi-turn outward travel or speculative commitments.\n            # From every chosen harvest destination, home is one move away.\n            if not 0 <= home_distance <= speed:\n                continue\n\n            # Do not initiate fights. Opponent capacity is still accounted for\n            # explicitly in the payout helper and in fallback allocations.\n            if opponent_capacity[node] > 0:\n                continue\n\n            before = served(\n                allocated_capacity[node], opponent_capacity[node], stock[node]\n            )\n            after = served(\n                allocated_capacity[node] + capacity,\n                opponent_capacity[node],\n                stock[node],\n            )\n            liability = return_liability(home_distance, speed, cost)\n            safe_gain = after - before - cost - liability + old_liability\n            if safe_gain < MIN_PROFIT:\n                continue\n\n            # Prefer strong immediate profit; favor nearby nodes on ties.\n            key = (safe_gain, -travel, -home_distance, -node)\n            if best_key is None or key > best_key:\n                best_key = key\n                destination = node\n\n        plan[uid] = destination\n        if destination != base:\n            allocated_capacity[destination] += capacity\n\n    return plan\n\n\ndef legal_action(plan, obs, distances):\n    """Validate each destination against the actual start-of-turn position."""\n    moves = {}\n    units = obs.get("player_units", {})\n    n = len(distances)\n    valid_ids = {\n        "T0", "T1", "T2", "T3",\n        "S0", "S1", "S2", "S3", "S4", "S5", "S6", "S7",\n    }\n    for uid in sorted(plan):\n        if uid not in valid_ids or uid not in units:\n            continue\n        unit_type, position = units[uid]\n        if unit_type not in UNIT_TYPES or not 0 <= position < n:\n            continue\n        destination = int(plan[uid])\n        if not 0 <= destination < n:\n            continue\n        distance = distances[position][destination]\n        if not 0 <= distance <= UNIT_TYPES[unit_type][2]:\n            continue\n        if destination != position:\n            moves[str(uid)] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self._map_key = None\n        self._distances = None\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": {}}\n        edges = tuple((int(u), int(v)) for u, v in obs.get("edges", []))\n        key = (n, edges)\n        if self._map_key != key:\n            self._distances = preprocess_map(n, edges)\n            self._map_key = key\n\n        # All work is bounded by 13 nodes and 12 couriers: no search,\n        # simulation, randomization, or growing iterative optimization.\n        plan = make_plan(obs, self._distances)\n        return legal_action(plan, obs, self._distances)\n'
